import { CancellationScope, condition, defineSignal, setHandler, workflowInfo } from "@temporalio/workflow";
import type { Handoff, PlanDecision, RunState } from "@rhinohealth/ai-agents-shared"; // Handoff: { key, requester, drill? } (G4-04)
import { act } from "../policies.js"; // proxied activities: 7-day start-to-close as a safety net, 2-minute heartbeats (G3-29)
import { waitForPerson } from "../waiting.js"; // reminders, then parking (G3-38); no VM runs while we wait
export const decidePlan = defineSignal<[PlanDecision]>("decidePlan"); // Slack buttons (G3-35)
export const answerQuestion = defineSignal<[text: string, by: string]>("answerQuestion"); // a reply in the ticket's thread
export async function ticketToPr(t: Handoff): Promise<string> { // workflow ID "nova:RH-1234": one run per ticket (G3-25)
  const run: RunState = { stopped: false }; // shared with G4-12's grill block and the Stop button (G3-38)
  let decision: PlanDecision | undefined;
  setHandler(decidePlan, (d) => { decision = d; });
  setHandler(answerQuestion, (text) => { run.answer = text; });
  const base = await act.mainHead(); // plan and build start from the same main commit
  const inSandbox = async (task: Task, size: Size): Promise<RunResult> => {
    const vm = await act.acquireSandbox({ runId: workflowInfo().runId, size, agent: "nova", jiraKey: t.key });
    try {
      await act.freshenSandbox(vm, base);
      run.answer = undefined; // cleared before the run, so a quick reply to its question is never lost
      let result = await act.workInSandbox(vm, task); // heartbeats; no work-time limit

      while (result.needsAnswer) {
        const idle = !(await condition(() => run.answer !== undefined, "10 minutes")); // no answer yet
        if (idle) await act.parkSandbox(vm); // stop the VM and keep its disk while a person thinks (G3-20)
        if (!(await waitForPerson(run, "question", () => run.answer !== undefined, t))) return { ...result, parked: true };
        if (idle) await act.wakeSandbox(vm); // start it again, freshen if main moved (G3-20)
        const reply = run.answer ?? ""; run.answer = undefined;
        result = await act.workInSandbox(vm, resumeTask(task, result.sessionId, reply));
      }
      return result;
    } finally {
      await CancellationScope.nonCancellable(() => act.releaseSandbox(vm)); // always: no VM is left behind
    }
  };
  const plan = await inSandbox(planTask(t), "lite"); // plan small
  if (plan.parked) return "parked";
  await act.postPlan(t, plan);
  if (!(await waitForPerson(run, "plan", () => decision !== undefined, t))) return "parked"; // remind at 1 day, park at 3
  if (decision?.kind !== "approve") return "stopped";
  const built = await inSandbox(buildTask(t, plan), "full"); // build big
  return built.parked ? "parked" : built.prUrl;
}

import { proxyActivities, type ActivityOptions, type RetryPolicy } from "@temporalio/workflow";
import type * as activities from "./activities/index.js";

const NEVER_RETRY = ["ScopeDenied", "PlanRejected", "NeedsPerson", "StoppedByPerson"];
export const AWS: RetryPolicy = { initialInterval: "1s", backoffCoefficient: 2, maximumInterval: "1 minute",
  maximumAttempts: 10, nonRetryableErrorTypes: NEVER_RETRY };
export const PEOPLE_APIS: RetryPolicy = { initialInterval: "5s", backoffCoefficient: 2, maximumInterval: "5 minutes",
  nonRetryableErrorTypes: NEVER_RETRY }; // no attempt limit: G3-39 pauses the ticket on long outages
export const HARNESS_STEP: RetryPolicy = { maximumAttempts: 1 }; // recovery (G3-27) decides, not blind retries

export const SHORT: ActivityOptions = { startToCloseTimeout: "5 minutes" };
// startToCloseTimeout is required by the SDK and is NOT a work limit: when 7 days pass, the retry re-attaches to the
// harness still running on the VM. The 2-minute heartbeat is what catches a dead worker.
export const LONG: ActivityOptions = { startToCloseTimeout: "7 days", heartbeatTimeout: "2 minutes" };

/** One place for timeouts and retries, so every workflow behaves the same (by default LONG, with AWS retries). */
export const act = proxyActivities<typeof activities>({ ...LONG, retry: AWS });
export const peopleApis = proxyActivities<typeof activities>({ ...SHORT, retry: PEOPLE_APIS });

import { test } from "node:test";
import { readdir, readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { Worker } from "@temporalio/worker";

test("saved workflow histories still replay", async () => {
  const workflowsPath = fileURLToPath(new URL("../src/workflows/index.ts", import.meta.url));
  const dir = new URL("./histories/", import.meta.url); // next to this file: npm test runs from the repo root
  for (const file of (await readdir(dir)).filter((f) => f.endsWith(".json")).sort()) {
    const history = JSON.parse(await readFile(new URL(file, dir), "utf8"));
    await Worker.runReplayHistory({ workflowsPath }, history, file);
  }
});

// Only the orchestrator starts runs.
import type { Client, Workflow } from "@temporalio/client";
import { defineSearchAttributeKey, SearchAttributeType, TypedSearchAttributes, WorkflowIdConflictPolicy } from "@temporalio/common";

const AGENT = defineSearchAttributeKey("Agent", SearchAttributeType.KEYWORD);

export const startRun = (client: Client, agent: string, thing: string, wf: string | Workflow, ...args: unknown[]) =>
  client.workflow.start(wf, {
    workflowId: `${agent}:${thing}`, // nova:RH-1234 | cifix:fcp:<fingerprint> | upgrade:fcp:pr-<n> | bugfix:RH-1240
    taskQueue: `ai-agents-${agent}`, // one queue per agent: nobody starves anybody
    workflowIdConflictPolicy: WorkflowIdConflictPolicy.USE_EXISTING, // a second trigger joins the open run
    typedSearchAttributes: new TypedSearchAttributes([{ key: AGENT, value: agent }]),
    args,
  });

// ID "slots:<agent>"; lives forever, continues-as-new now and then.
import { condition, continueAsNew, defineSignal, getExternalWorkflowHandle, setHandler, workflowInfo } from "@temporalio/workflow";

export const SLOTS: Record<string, number> = { nova: 3, cifix: 2, upgrade: 2, flaky: 1, bugfix: 2, health: 1, security: 1 }; // VMs in parallel per agent, to start
export const request = defineSignal<[workflowId: string]>("request");
export const release = defineSignal<[workflowId: string]>("release"); // on park (VM stopped) and at the end of a run
export const slotGranted = defineSignal("slotGranted");

export async function slots(agent: string, holders: string[] = [], waiting: string[] = []): Promise<void> {
  setHandler(request, (id) => { waiting.push(id); });
  setHandler(release, (id) => { holders = holders.filter((h) => h !== id); });
  while (workflowInfo().historyLength < 5000) {
    await condition(() => waiting.length > 0 && holders.length < (SLOTS[agent] ?? 1));
    const holder = waiting.shift()!;
    holders.push(holder);
    await getExternalWorkflowHandle(holder).signal(slotGranted);
  }
  await continueAsNew<typeof slots>(agent, holders, waiting); // carries holders and waiting along
}

// A sketch built from the ticket's steps: hold a slot only while a VM runs.
import { CancellationScope, condition, getExternalWorkflowHandle, setHandler, workflowInfo } from "@temporalio/workflow";
import { release, request, slotGranted } from "./slots.js";

export const withSlot = async <T>(agent: string, fn: () => Promise<T>): Promise<T> => {
  const me = workflowInfo().workflowId; // nova:RH-1234
  const line = getExternalWorkflowHandle(`slots:${agent}`);
  let granted = false;
  setHandler(slotGranted, () => { granted = true; });
  await line.signal(request, me); // join the line
  await condition(() => granted); // waits as long as it takes; costs nothing
  try {
    return await fn(); // claim, freshen and run the VM inside the slot
  } finally {
    await CancellationScope.nonCancellable(() => line.signal(release, me)); // give the slot back
  }
};

