import { CancellationScope, condition, defineSignal, proxyActivities, setHandler } from "@temporalio/workflow";
import type * as activities from "./activities.js";

const act = proxyActivities<typeof activities>({ startToCloseTimeout: "7 days", heartbeatTimeout: "2 minutes" });
export interface Handoff { key: string; requester: string }
export interface PlanDecision { kind: "approve" | "change" | "reject" }
export const decidePlan = defineSignal<[PlanDecision]>("decidePlan");

export async function ticketToPr(t: Handoff): Promise<string> {
  let decision: PlanDecision | undefined;
  setHandler(decidePlan, (d) => { decision = d; });
  const inSandbox = async (task: string, size: "lite" | "full") => {
    const vm = await act.acquireSandbox(size);
    try {
      return await act.workInSandbox(vm, task);
    } finally {
      await CancellationScope.nonCancellable(() => act.releaseSandbox(vm));
    }
  };
  await inSandbox(`plan ${t.key}`, "lite");
  await act.postPlan(t.key);
  if (!(await condition(() => decision !== undefined, "3 days"))) return "parked";
  if (decision?.kind !== "approve") return "stopped";
  const built = await inSandbox(`build ${t.key}`, "full");
  return built.prUrl ?? "no PR";
}

