import { after, before, test } from "node:test";
import assert from "node:assert/strict";
import { fileURLToPath } from "node:url";
import { TestWorkflowEnvironment } from "@temporalio/testing";
import { Worker } from "@temporalio/worker";
import { decidePlan, ticketToPr } from "../src/workflows.js";
import type { Sandbox } from "../src/activities.js";

let env: TestWorkflowEnvironment;
before(async () => { env = await TestWorkflowEnvironment.createTimeSkipping(); });
after(async () => { await env?.teardown(); });

const released: string[] = [];
const mocks = {
  acquireSandbox: async (size: "lite" | "full"): Promise<Sandbox> => ({ id: `i-${size}`, size }),
  workInSandbox: async (vm: Sandbox) => (vm.size === "full" ? { prUrl: "https://github.com/x/pull/1" } : {}),
  postPlan: async () => {},
  releaseSandbox: async (vm: Sandbox) => { released.push(vm.id); },
};
const run = async (fn: (id: string) => Promise<string>) => {
  const worker = await Worker.create({
    connection: env.nativeConnection, taskQueue: "test",
    workflowsPath: fileURLToPath(new URL("../src/workflows.ts", import.meta.url)), activities: mocks,
  });
  return worker.runUntil(fn(`nova:RH-${released.length}`));
};

test("approve: plan on lite, build on full, both VMs released", async () => {
  released.length = 0;
  const result = await run(async (workflowId) => {
    const handle = await env.client.workflow.start(ticketToPr, { taskQueue: "test", workflowId, args: [{ key: "RH-1", requester: "sean" }] });
    await handle.signal(decidePlan, { kind: "approve" });
    return handle.result();
  });
  assert.equal(result, "https://github.com/x/pull/1");
  assert.deepEqual(released, ["i-lite", "i-full"]);
});

test("reject: stopped, no full VM", async () => {
  released.length = 0;
  const result = await run(async (workflowId) => {
    const handle = await env.client.workflow.start(ticketToPr, { taskQueue: "test", workflowId: workflowId + "r", args: [{ key: "RH-2", requester: "sean" }] });
    await handle.signal(decidePlan, { kind: "reject" });
    return handle.result();
  });
  assert.equal(result, "stopped");
  assert.deepEqual(released, ["i-lite"]);
});
